package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Comment;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_siblingIndex_TriageGen2Test {

    @Test
    public void testSiblingIndex_Element() {
        Node node = new Element("test");
        node.siblingIndex = 5;
        assertEquals(5, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_TextNode() {
        Node node = new TextNode("test");
        node.siblingIndex = 5;
        assertEquals(5, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_Comment() {
        Node node = new Comment("test");
        node.siblingIndex = 5;
        assertEquals(5, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_Document() {
        Document document = new Document();
        Node node = document.body();
        node.siblingIndex = 5;
        assertEquals(5, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_Null() {
        Node node = null;
        try {
            node.siblingIndex();
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // expected
        }
    }

    @Test
    public void testSiblingIndex_SetSiblingIndex() {
        Node node = new Element("test");
        node.setSiblingIndex(5);
        assertEquals(5, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_ResetSiblingIndex() {
        Node node = new Element("test");
        node.siblingIndex = 5;
        node.setSiblingIndex(0);
        assertEquals(0, node.siblingIndex());
    }
}
